$('#deleteAnchor').onclick=()=>{const paths=fvsPathOnly('Delete Anchor');if(!paths||paths.length!==1){if(paths)$('#status').textContent='Delete Anchor needs exactly one selected path.';return}const e=paths[0],segs=fvsAbsolutePath(e.getAttribute('d')||''),ix=(directNode&&directNode.path===e?fvsDirectSegIndex(e,directNode.i):fvsAnchorIndexNearCenter(e,segs));if(ix<1||ix>=segs.length-1){$('#status').textContent='Choose a path with an interior anchor to delete.';return}const prev=segs[ix-1],cur=segs[ix],next=segs[ix+1];if(next.cmd==='Z'){ $('#status').textContent='Endpoint deletion on a closed seam is not enabled yet.';return}checkpoint('Delete Anchor');const start=fvsSegEnd(prev),end=fvsSegEnd(next);if(cur.cmd==='C'&&next.cmd==='C')next.nums=[cur.nums[0],cur.nums[1],next.nums[2],next.nums[3],...end];else if(cur.cmd==='Q'&&next.cmd==='Q')next.nums=[(cur.nums[0]+next.nums[0])/2,(cur.nums[1]+next.nums[1])/2,...end];else next.cmd='L',next.nums=end;segs.splice(ix,1);e.setAttribute('d',fvsPathD(segs));refresh();persist();$('#status').textContent='Interior anchor deleted; neighboring segment continuity retained where possible.'};
