function fvsPathNormal(path){try{const len=path.getTotalLength(),a=path.getPointAtLength(Math.max(0,len*.45)),b=path.getPointAtLength(Math.min(len,len*.55)),dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy)||1;return{x:-dy/n,y:dx/n}}catch{return{x:1,y:0}}}
function fvsParallelCopies(path){const q=fvsBrushSettings();if(q.parallel<2)return;const d=path.getAttribute('d'),stroke=path.getAttribute('stroke'),w=path.getAttribute('stroke-width'),normal=fvsPathNormal(path),master=objectKey(path),center=(q.parallel-1)/2;for(let i=0;i<q.parallel;i++){const offset=(i-center)*q.spacing,tx=normal.x*offset,ty=normal.y*offset;if(i===0){path.setAttribute('transform',(path.getAttribute('transform')||'')+' translate('+tx.toFixed(3)+' '+ty.toFixed(3)+')');path.dataset.parallelMaster=master;continue}const n=path.cloneNode(true);renewObjectKey(n);n.setAttribute('d',d);n.setAttribute('stroke',stroke);n.setAttribute('stroke-width',w);n.setAttribute('transform',(path.getAttribute('transform')||'').replace(/ translate\([^)]*\)\s*$/,'')+' translate('+tx.toFixed(3)+' '+ty.toFixed(3)+')');n.dataset.parallelMaster=master;content.append(n)}}
