const guides=$('#guides')||ui;
function fvsClearTypeGrid(){guides.querySelectorAll('.type-grid-guide').forEach(e=>e.remove())}
function fvsGridLine(x1,y1,x2,y2){const l=E('line');A(l,{x1,y1,x2,y2,class:'type-grid-guide'});guides.append(l)}
function fvsDrawTypeGrid(){fvsClearTypeGrid();const kind=$('#typeGridKind')?.value||'baseline',gap=Math.max(2,+($('#typeGridSpacing')?.value||24)),n=Math.max(1,+($('#typeGridDivisions')?.value||6));if(kind==='baseline'||kind==='cap'||kind==='xheight'){for(let y=gap;y<docHeight;y+=gap)fvsGridLine(0,y,docWidth,y)}else if(kind==='columns'){for(let i=1;i<n;i++){let x=docWidth*i/n;fvsGridLine(x,0,x,docHeight)}}else if(kind==='modular'){for(let x=gap;x<docWidth;x+=gap)fvsGridLine(x,0,x,docHeight);for(let y=gap;y<docHeight;y+=gap)fvsGridLine(0,y,docWidth,y)}else if(kind==='radial'){let cx=docWidth/2,cy=docHeight/2,r=Math.hypot(docWidth,docHeight);for(let i=0;i<n;i++){let a=i*Math.PI/n;fvsGridLine(cx-Math.cos(a)*r,cy-Math.sin(a)*r,cx+Math.cos(a)*r,cy+Math.sin(a)*r)}}else if(kind==='isometric'){for(let x=-docHeight;x<docWidth+docHeight;x+=gap){fvsGridLine(x,0,x+docHeight*.577,docHeight);fvsGridLine(x,0,x-docHeight*.577,docHeight)}}else if(kind==='perspective'){let cx=docWidth/2,cy=docHeight/2;for(let x=0;x<=docWidth;x+=gap)fvsGridLine(cx,cy,x,docHeight);for(let y=0;y<=docHeight;y+=gap)fvsGridLine(0,y,docWidth,y)}else if(kind==='golden'){let phi=1.61803398875,x=docWidth/phi,y=docHeight/phi;fvsGridLine(x,0,x,docHeight);fvsGridLine(docWidth-x,0,docWidth-x,docHeight);fvsGridLine(0,y,docWidth,y);fvsGridLine(0,docHeight-y,docWidth,docHeight-y)}}
$('#showTypeGrid')?.addEventListener('click',fvsDrawTypeGrid);$('#clearTypeGrid')?.addEventListener('click',fvsClearTypeGrid);

function fvsPhysicsDefaults(){return{enabled:false,mass:1,gravity:1,friction:.3,bounce:.2,wind:0,locked:false}}
function fvsGetPhysics(el){if(!el)return fvsPhysicsDefaults();try{return Object.assign(fvsPhysicsDefaults(),JSON.parse(el.dataset.fvsPhysics||'{}'))}catch{return fvsPhysicsDefaults()}}
function fvsSetPhysics(el,patch){if(!el)return;el.dataset.fvsPhysics=JSON.stringify(Object.assign(fvsGetPhysics(el),patch))}
function fvsPhysicsProxy(el){try{const b=el.getBBox(),q=fvsGetPhysics(el);return{x:b.x,y:b.y,w:b.width,h:b.height,cx:b.x+b.width/2,cy:b.y+b.height/2,mass:q.mass,gravity:q.gravity,friction:q.friction,bounce:q.bounce,wind:q.wind||0,locked:q.locked}}catch{return null}}
function fvsSillysicsSettings(){return{mode:$('#sillysicsMode')?.value||'off',intensity:Math.max(0,Math.min(100,+($('#sillysicsIntensity')?.value||55)))}}
function fvsApplySillysics(el,q=fvsSillysicsSettings()){if(!el)return;el.dataset.fvsSillysics=JSON.stringify(q)}
function fvsSillysicsTransform(el,q=fvsSillysicsSettings()){if(!el||q.mode==='off')return'';const k=q.intensity/100,b=el.getBBox(),cx=b.x+b.width/2,cy=b.y+b.height/2;if(q.mode==='boing')return ' translate('+cx+' '+cy+') scale('+(1+.16*k)+' '+(1-.12*k)+') translate('+(-cx)+' '+(-cy)+')';if(q.mode==='wobble')return ' rotate('+(8*k)+' '+cx+' '+cy+') skewX('+(6*k)+')';if(q.mode==='floaty')return ' translate(0 '+(-24*k)+') rotate('+(-3*k)+' '+cx+' '+cy+')';return ' translate('+(12*k)+' '+(-10*k)+') rotate('+(14*k)+' '+cx+' '+cy+') scale('+(1+.08*k)+' '+(1+.04*k)+')'}
$('#applySillysics')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Apply Sillysics',true);const q=fvsSillysicsSettings();sel.forEach(e=>fvsApplySillysics(e,q));persist();$('#status').textContent=q.mode==='off'?'Sillysics disabled on selection.':'Sillysics '+q.mode+' attached nondestructively.'});
$('#previewSillysics')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Preview Sillysics');const q=fvsSillysicsSettings();sel.forEach(e=>{fvsApplySillysics(e,q);const base=e.dataset.fvsSillysicsBaseTransform??e.getAttribute('transform')??'';if(e.dataset.fvsSillysicsBaseTransform==null)e.dataset.fvsSillysicsBaseTransform=base;e.setAttribute('transform',base+fvsSillysicsTransform(e,q))});refresh();persist();$('#status').textContent=q.mode==='off'?'Sillysics preview off.':'Sillysics preview: '+q.mode+'. Original geometry preserved.'});

function fvsBrushPreview(){const p=$('#brushPreviewPath'),q=fvsBrushSettings();if(!p)return;p.setAttribute('stroke',$('#stroke')?.value||'#26323c');p.setAttribute('stroke-width',q.size);p.setAttribute('fill','none');p.setAttribute('stroke-linecap','round');p.setAttribute('stroke-linejoin','round');p.setAttribute('opacity',Math.max(.35,1-q.variation/180))}
function fvsSmoothPathD(d,amount){if(!amount)return d;const nums=(d.match(/-?\d*\.?\d+/g)||[]).map(Number);if(nums.length<6)return d;const pts=[];for(let i=0;i+1<nums.length;i+=2)pts.push([nums[i],nums[i+1]]);const passes=Math.min(4,Math.max(0,Math.round(amount/25)));for(let k=0;k<passes;k++)for(let i=1;i<pts.length-1;i++){pts[i][0]=(pts[i-1][0]+pts[i][0]*2+pts[i+1][0])/4;pts[i][1]=(pts[i-1][1]+pts[i][1]*2+pts[i+1][1])/4}return pts.length?'M '+pts.map(p=>p[0].toFixed(2)+' '+p[1].toFixed(2)).join(' L '):d}
function fvsFinalizeBrushPath(path){const q=fvsBrushSettings();if(q.liveSmooth)path.setAttribute('d',fvsSmoothPathD(path.getAttribute('d')||'',q.smoothing));path.dataset.fvsBrush=JSON.stringify(q);fvsBrushPreview()}
['#brushFeel','#brushMode','#brushPressureWidth','#brushLiveSmooth'].forEach(s=>$(s)?.addEventListener('change',()=>{fvsBrushCoach();fvsBrushPreview()}));
['#brushSize','#brushSmooth','#brushTaper','#brushVariation','#brushScatter','#brushRotation','#brushPressure','#parallelSpacing'].forEach(s=>$(s)?.addEventListener('input',fvsBrushPreview));
fvsBrushPreview();

$('#procreateImport')?.addEventListener('click',()=>$('#procreateFile')?.click());
$('#procreateFile')?.addEventListener('change',e=>{const file=e.target.files?.[0],s=$('#procreateStatus');if(!file)return;const ext=(file.name.split('.').pop()||'').toLowerCase();if(ext==='psd'){s.textContent='PSD selected. Layer-preserving PSD parsing is not installed yet; file left untouched.';return}if(ext==='svg'){const rd=new FileReader();rd.onload=()=>{const m=String(rd.result).match(/<svg[^>]*>([\s\S]*)<\/svg>/i);if(!m){s.textContent='SVG could not be parsed.';return}checkpoint('Import SVG',true);const g=make('g','Procreate Bridge SVG');g.innerHTML=m[1];selected(g);persist();s.textContent='SVG imported as editable vector artwork.'};rd.readAsText(file);return}if(['png','jpg','jpeg'].includes(ext)){const rd=new FileReader();rd.onload=()=>{checkpoint('Import raster artwork',true);const im=make('image','Procreate Raster');A(im,{href:rd.result,x:0,y:0,width:docWidth,height:docHeight,preserveAspectRatio:'xMidYMid meet'});selected(im);persist();s.textContent='Raster artwork imported. Use Image Trace/Vectorize when editable vectors are needed.'};rd.readAsDataURL(file);return}s.textContent='This format is recognized but not yet decoded in the current source build.'});
$('#procreateExport')?.addEventListener('click',()=>{const s=$('#procreateStatus'),p=$('#procreatePreset')?.value;if(p==='svg'){const blob=new Blob([svg.outerHTML],{type:'image/svg+xml'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fvs-procreate-bridge.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);s.textContent='Editable SVG export prepared.';return}s.textContent=p==='psd-note'?'PSD export requires the layered PSD encoder planned for the desktop bridge. No fake PSD was generated.':'Raster export renderer is the next bridge stage; no low-quality placeholder was generated.'});

$('#applyPhysics')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Physics settings');const patch={enabled:!!$('#physicsEnabled')?.checked,mass:+($('#physicsMass')?.value||1),gravity:+($('#physicsGravity')?.value||1),friction:+($('#physicsFriction')?.value||30)/100,bounce:+($('#physicsBounce')?.value||20)/100,wind:+($('#physicsWind')?.value||0)};sel.forEach(e=>fvsSetPhysics(e,patch));persist();$('#status').textContent='Physics settings attached nondestructively.'});
function fvsResetPhysicsPreview(){sel.forEach(e=>{if(e.dataset.fvsPhysicsBaseTransform!=null){e.setAttribute('transform',e.dataset.fvsPhysicsBaseTransform);delete e.dataset.fvsPhysicsBaseTransform}delete e.dataset.fvsPhysicsVelocity});refresh();persist()}
$('#previewPhysics')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Physics simulation');const steps=Math.max(1,Math.min(120,+($('#physicsSteps')?.value||12))),dt=1/12;for(const e of sel){const q=fvsGetPhysics(e),b=fvsPhysicsProxy(e);if(!q.enabled||q.locked||!b)continue;if(e.dataset.fvsPhysicsBaseTransform==null)e.dataset.fvsPhysicsBaseTransform=e.getAttribute('transform')||'';let v={x:0,y:0};try{v=Object.assign(v,JSON.parse(e.dataset.fvsPhysicsVelocity||'{}'))}catch{}let x=0,y=0;for(let i=0;i<steps;i++){v.x+=(q.wind||0)*18*dt/Math.max(.1,q.mass);v.y+=q.gravity*36*dt/Math.max(.1,q.mass);v.x*=Math.max(0,1-q.friction*dt);v.y*=Math.max(0,1-q.friction*dt);x+=v.x*dt;y+=v.y*dt;const floor=docHeight-(b.y+b.h);if(y>floor){y=floor;v.y=-Math.abs(v.y)*q.bounce}}e.dataset.fvsPhysicsVelocity=JSON.stringify(v);e.setAttribute('transform',e.dataset.fvsPhysicsBaseTransform+' translate('+x.toFixed(3)+' '+y.toFixed(3)+')')}refresh();persist();$('#status').textContent='Vector Physics simulated '+steps+' steps with gravity, wind, friction, bounce, and floor collision.'});
$('#resetPhysics')?.addEventListener('click',fvsResetPhysicsPreview);
$('#freezePhysics')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Freeze Physics State',true);sel.forEach(e=>{delete e.dataset.fvsPhysicsBaseTransform;delete e.dataset.fvsPhysicsVelocity;e.dataset.fvsPhysicsFrozen='1'});persist();$('#status').textContent='Physics state frozen as the new editable transform state.'});

$('#iccFile')?.addEventListener('change',e=>{const file=e.target.files?.[0],s=$('#iccStatus');if(!file)return;const rd=new FileReader();rd.onload=()=>{const bytes=new Uint8Array(rd.result),sig=bytes.length>39?String.fromCharCode(...bytes.slice(36,40)):'';if(sig!=='acsp'){s.textContent='Rejected: this file does not contain the ICC profile signature.';return}window.__fvsICC={name:file.name,size:file.size,bytes};if($('#printProfile'))$('#printProfile').value='icc-custom';s.textContent='ICC profile loaded: '+file.name+'. Transform engine validation is still required before press-accurate soft proofing.';fvsColorAdvancedReadout()};rd.readAsArrayBuffer(file)});

$('#mirrorCopy')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Mirror Copy');const made=[];for(const e of sel){const b=e.getBBox(),n=e.cloneNode(true);objectKey(n);n.dataset.name=(e.dataset.name||e.tagName)+' Mirror';n.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+(2*(b.x+b.width/2))+' 0) scale(-1 1)');content.append(n);made.push(n)}sel=made;refresh();persist()});
$('#radialRepeat')?.addEventListener('click',()=>{if(sel.length!==1)return;checkpoint('Radial Repeat',true);const e=sel[0],b=e.getBBox(),cx=b.x+b.width/2,cy=b.y+b.height/2,n=Math.max(2,+($('#repeatCopies')?.value||8)),ang=+($('#repeatAngle')?.value||360/n),scale=(+($('#repeatScale')?.value||100))/100,made=[e];for(let i=1;i<n;i++){const q=e.cloneNode(true);renewObjectKey(q);q.dataset.name=(e.dataset.name||e.tagName)+' Repeat '+(i+1);q.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+cx+' '+cy+') rotate('+(ang*i)+') scale('+(Math.pow(scale,i))+') translate('+(-cx)+' '+(-cy)+')');content.append(q);made.push(q)}sel=made;refresh();persist()});
$('#pixelSnap')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Pixel Snap');sel.forEach(e=>{const b=e.getBBox(),dx=Math.round(b.x)-b.x,dy=Math.round(b.y)-b.y;e.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+dx+' '+dy+')')});refresh();persist()});
$('#fitArtboard')?.addEventListener('click',()=>{if(sel.length!==1)return;const a=fvsActiveArtboard();if(!a)return;checkpoint('Fit to Active Artboard');const e=sel[0],b=e.getBBox();if(!b.width||!b.height)return;const z=Math.min(a.width/b.width,a.height/b.height),tx=a.x+(a.width-b.width*z)/2-b.x*z,ty=a.y+(a.height-b.height*z)/2-b.y*z;e.setAttribute('transform','translate('+tx+' '+ty+') scale('+z+')');refresh();persist()});
$('#applyLiveCorners')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Live Corners');const r=Math.max(0,+($('#liveCornerRadius')?.value||0));for(const e of sel){if(e.tagName==='rect'){e.setAttribute('rx',r);e.setAttribute('ry',r);e.dataset.fvsCornerRadius=r}else e.dataset.fvsCornerRadius=r}refresh();persist();$('#status').textContent='Live corner radius stored'+(sel.some(e=>e.tagName!=='rect')?' for compatible path expansion.':' and applied.')});

function fvsPreflight(){const els=[...content.querySelectorAll('*')],issues=[];let hidden=0,empty=0,raster=0,ids=0,wide=0;for(const e of els){if(e.style?.display==='none')hidden++;if(e.tagName==='path'&&!(e.getAttribute('d')||'').trim())empty++;if(e.tagName==='image')raster++;if(!e.dataset?.fvsid&&['path','rect','ellipse','polygon','text','image','g'].includes(e.tagName))ids++;if(+(e.getAttribute('stroke-width')||0)>100)wide++}if(hidden)issues.push(hidden+' hidden object'+(hidden===1?'':'s'));if(empty)issues.push(empty+' empty path'+(empty===1?'':'s'));if(raster)issues.push(raster+' raster asset'+(raster===1?'':'s')+' to verify for resolution/profile');if(ids)issues.push(ids+' object'+(ids===1?'':'s')+' without Shape Memory IDs');if(wide)issues.push(wide+' extreme stroke'+(wide===1?'':'s'));return issues}
function fvsMarketIssues(target){const a=fvsActiveArtboard(),issues=[],objs=[...content.children].filter(e=>e.style.display!=='none');if(!objs.length)issues.push('No visible artwork.');for(const e of objs){if(!fvsOnArtboard(e,a))issues.push((e.dataset.name||e.tagName)+' extends outside the active artboard.');if(e.tagName==='image')issues.push('Raster image found: '+(e.dataset.name||'Image')+'.');if(e.tagName==='text'||e.tagName==='foreignObject')issues.push('Live text found. Create outlines or include font/licensing instructions.');if(e.tagName==='path'&&!(e.getAttribute('d')||'').trim())issues.push('Empty path found.')}if(target==='adobe-stock'){if(artboards.length!==1)issues.push('Adobe Stock vector export should contain one artboard.');if(a&&(a.x!==0||a.y!==0))issues.push('Adobe Stock active artboard should begin at 0,0.');if(a&&a.width*a.height<15000000)issues.push('Adobe Stock vector artboard is below 15 MP.');}return[...new Set(issues)]}
function fvsPublishPlan(){const destination=$('#publishDestination')?.value||'seller-pack',output=$('#productOutput')?.value||'single',title=$('#marketTitle')?.value.trim()||'Untitled Vector Asset',keywords=$('#marketKeywords')?.value.split(',').map(x=>x.trim()).filter(Boolean);const variants=output==='five'?['Editable Vector','Transparent PNG','Seamless Pattern','Background / Print','Commercial Bundle']:output==='pattern'?['Seamless Tile','Repeat Preview','Transparent Elements','Alternate Layout','Pattern Bundle']:output==='bundle'?['Editable Vector','High Resolution PNG','Preview','Pattern / Background','Commercial Bundle']:['Primary Asset'];return{destination,output,title,keywords,variants,artboard:fvsActiveArtboard(),created:new Date().toISOString()}}
$('#publishProduct')?.addEventListener('click',()=>{const plan=fvsPublishPlan(),target=plan.destination==='adobe-stock'?'adobe-stock':plan.destination==='creative-market'?'creative-market':'generic',issues=fvsMarketIssues(target);if(issues.length){$('#marketReadout').textContent='Upload preparation blocked: '+issues[0];return}if(plan.destination==='fluid-stock'){download((plan.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'fluid-stock-product')+'-publish-plan.json',JSON.stringify(plan,null,2),'application/json');$('#marketReadout').textContent='Fluid Stock publish plan prepared with '+plan.variants.length+' product output'+(plan.variants.length===1?'':'s')+'. Direct site publishing will activate when the Fluid Stock endpoint is connected.';return}download((plan.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'product')+'-'+plan.destination+'-upload-plan.json',JSON.stringify(plan,null,2),'application/json');$('#marketReadout').textContent=plan.destination+' upload package plan prepared with '+plan.variants.length+' output'+(plan.variants.length===1?'':'s')+'.';});
$('#marketPreflight')?.addEventListener('click',()=>{const target=$('#marketTarget').value,issues=fvsMarketIssues(target);$('#marketReadout').textContent=issues.length?issues.length+' issue'+(issues.length===1?'':'s')+': '+issues.slice(0,5).join(' • '):'Marketplace quality check passed for the selected profile.';});
$('#marketClean')?.addEventListener('click',()=>{checkpoint('Marketplace cleanup',true);[...content.children].forEach(e=>{if(e.style.display==='none'||(e.tagName==='path'&&!(e.getAttribute('d')||'').trim()))e.remove()});refresh();persist();$('#marketReadout').textContent='Removed hidden artwork and empty paths from the working document. Run Quality Check again.';});
$('#marketPreview')?.addEventListener('click',()=>$('#pngExport')?.click());
$('#marketPackage')?.addEventListener('click',()=>{const target=$('#marketTarget').value,issues=fvsMarketIssues(target);if(issues.length){$('#marketReadout').textContent='Seller Pack blocked until quality issues are cleared. '+issues[0];return}const title=$('#marketTitle').value.trim()||'Untitled Vector Asset',keywords=$('#marketKeywords').value.split(',').map(x=>x.trim()).filter(Boolean),manifest={product:title,target,keywords,created:new Date().toISOString(),artboard:fvsActiveArtboard(),formats:['SVG','PNG preview'],notes:'Editable vector artwork. Verify marketplace-specific licensing and metadata before submission.'};download((title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'vector-asset')+'-seller-manifest.json',JSON.stringify(manifest,null,2),'application/json');$('#marketReadout').textContent='Seller manifest created. Export the SVG and PNG preview to complete this marketplace pack.';});
