$('#centerArt')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Center Artwork');for(const e of sel){const b=e.getBBox(),dx=docWidth/2-(b.x+b.width/2),dy=docHeight/2-(b.y+b.height/2);e.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+dx+' '+dy+')')}refresh();persist()});
$('#stepRepeat')?.addEventListener('click',()=>{if(sel.length!==1)return;checkpoint('Step and Repeat');const e=sel[0],n=e.cloneNode(true),dx=+($('#stepX')?.value||0),dy=+($('#stepY')?.value||0);objectKey(n);n.dataset.name=(e.dataset.name||e.tagName)+' Repeat';n.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+dx+' '+dy+')');content.append(n);sel=[n];refresh();persist()});
$('#symmetryCopy')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Symmetry Copy');const axis=$('#symmetryAxis')?.value||'vertical',made=[];for(const e of sel){const b=e.getBBox(),cx=b.x+b.width/2,cy=b.y+b.height/2,n=e.cloneNode(true);objectKey(n);n.dataset.name=(e.dataset.name||e.tagName)+' Symmetry';let t=e.getAttribute('transform')||'';if(axis==='vertical')t+=' translate('+(2*cx)+' 0) scale(-1 1)';else if(axis==='horizontal')t+=' translate(0 '+(2*cy)+') scale(1 -1)';else t+=' translate('+(2*cx)+' '+(2*cy)+') scale(-1 -1)';n.setAttribute('transform',t);content.append(n);made.push(n)}sel=made;refresh();persist()});

function fvsRgbHsl(a){let r=a[0]/255,g=a[1]/255,b=a[2]/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,h=0,l=(max+min)/2,s=d===0?0:d/(1-Math.abs(2*l-1));if(d){if(max===r)h=60*(((g-b)/d)%6);else if(max===g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4)}if(h<0)h+=360;return[h,s*100,l*100]}
function fvsRgbHsv(a){let r=a[0]/255,g=a[1]/255,b=a[2]/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,h=0;if(d){if(max===r)h=60*(((g-b)/d)%6);else if(max===g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4)}if(h<0)h+=360;return[h,max?d/max*100:0,max*100]}
function fvsRgbOklab(a){let r=fvsRgbLinear(a[0]),g=fvsRgbLinear(a[1]),b=fvsRgbLinear(a[2]),l=Math.cbrt(.4122214708*r+.5363325363*g+.0514459929*b),m=Math.cbrt(.2119034982*r+.6806995451*g+.1073969566*b),s=Math.cbrt(.0883024619*r+.2817188376*g+.6299787005*b);return[.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s]}
function fvsOklabOklch(a){let C=Math.hypot(a[1],a[2]),H=Math.atan2(a[2],a[1])*180/Math.PI;if(H<0)H+=360;return[a[0],C,H]}

$('#applyLabColor')?.addEventListener('click',()=>{const h=$('#colorHex'),rgb=h&&fvsHexRgb(h.value);if(!rgb)return;const hex='#'+rgb.map(n=>n.toString(16).padStart(2,'0')).join('');$('#fill').value=hex;if(sel.length)eachSel(e=>e.setAttribute('fill',hex));fvsColorAdvancedReadout();$('#status').textContent='Color Universe color applied to fill.'});
function fvsRestoreDocumentSwatches(){const box=$('#swatches');if(!box)return;let saved=[];try{saved=JSON.parse(localStorage.getItem('fvs-document-swatches')||'[]')}catch{};saved.forEach(hex=>{if(!/^#[0-9a-f]{6}$/i.test(hex)||[...box.querySelectorAll('[data-swatch]')].some(b=>b.dataset.swatch.toLowerCase()===hex.toLowerCase()))return;const b=document.createElement('button');b.dataset.swatch=hex;b.style.background=hex;b.title=hex;b.addEventListener('click',()=>{$('#fill').value=hex;eachSel(e=>e.setAttribute('fill',hex))});box.append(b)})}
fvsRestoreDocumentSwatches();
$('#addLabSwatch')?.addEventListener('click',()=>{const h=$('#colorHex'),rgb=h&&fvsHexRgb(h.value),box=$('#swatches');if(!rgb||!box)return;const hex='#'+rgb.map(n=>n.toString(16).padStart(2,'0')).join('');if([...box.querySelectorAll('[data-swatch]')].some(b=>b.dataset.swatch.toLowerCase()===hex))return;const b=document.createElement('button');b.dataset.swatch=hex;b.style.background=hex;b.title=hex;b.addEventListener('click',()=>{$('#fill').value=hex;eachSel(e=>e.setAttribute('fill',hex))});box.append(b);const saved=JSON.parse(localStorage.getItem('fvs-document-swatches')||'[]');saved.push(hex);localStorage.setItem('fvs-document-swatches',JSON.stringify([...new Set(saved)]));$('#status').textContent='Document swatch added: '+hex});

function fvsTransformAboutCenter(e,op){const b=e.getBBox(),cx=b.x+b.width/2,cy=b.y+b.height/2;e.setAttribute('transform',(e.getAttribute('transform')||'')+' translate('+cx+' '+cy+') '+op+' translate('+(-cx)+' '+(-cy)+')')}
$('#rotateLeft')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Rotate');let a=+($('#angleStep')?.value||15);sel.forEach(e=>fvsTransformAboutCenter(e,'rotate('+(-a)+')'));refresh();persist()});
$('#rotateRight')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Rotate');let a=+($('#angleStep')?.value||15);sel.forEach(e=>fvsTransformAboutCenter(e,'rotate('+a+')'));refresh();persist()});
$('#flipH')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Flip Horizontal');sel.forEach(e=>fvsTransformAboutCenter(e,'scale(-1 1)'));refresh();persist()});
$('#flipV')?.addEventListener('click',()=>{if(!sel.length)return;checkpoint('Flip Vertical');sel.forEach(e=>fvsTransformAboutCenter(e,'scale(1 -1)'));refresh();persist()});
document.addEventListener('keydown',e=>{if(!sel.length||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||/input|textarea|select/i.test(e.target?.tagName||''))return;e.preventDefault();checkpoint('Nudge');let s=+($('#nudgeStep')?.value||1)*(e.shiftKey?10:1),dx=e.key==='ArrowLeft'?-s:e.key==='ArrowRight'?s:0,dy=e.key==='ArrowUp'?-s:e.key==='ArrowDown'?s:0;sel.forEach(x=>x.setAttribute('transform',(x.getAttribute('transform')||'')+' translate('+dx+' '+dy+')'));refresh();persist()});

function fvsGeometry(e){if(!e)return null;const b=e.getBBox(),d=e.tagName==='path'?(e.getAttribute('d')||''):'';let length=0;try{length=e.getTotalLength?.()||0}catch{}const anchors=d?pathPoints(d).filter(p=>p.kind==='anchor').length:0;return{x:b.x,y:b.y,width:b.width,height:b.height,area:b.width*b.height,length,anchors,type:e.tagName,name:e.dataset.name||e.tagName}}
function fvsGeometryText(g){return g?'X '+g.x.toFixed(2)+' • Y '+g.y.toFixed(2)+' • W '+g.width.toFixed(2)+' • H '+g.height.toFixed(2)+' • Bounds area '+g.area.toFixed(2)+(g.length?' • Path '+g.length.toFixed(2):'')+(g.anchors?' • Anchors '+g.anchors:''):''}
$('#measureSelection')?.addEventListener('click',()=>{const o=$('#geometryReadout');if(!sel.length){o.textContent='Select artwork to measure.';return}o.textContent=sel.map(e=>fvsGeometryText(fvsGeometry(e))).join(' | ')});
$('#copyGeometry')?.addEventListener('click',async()=>{if(!sel.length)return;const t=sel.map(e=>fvsGeometryText(fvsGeometry(e))).join('\n');try{await navigator.clipboard.writeText(t);$('#status').textContent='Geometry copied.'}catch{$('#status').textContent=t}});

function fvsLum(hex){const a=fvsHexRgb(hex);if(!a)return null;const q=a.map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*q[0]+.7152*q[1]+.0722*q[2]}
function fvsContrast(a,b){const x=fvsLum(a),y=fvsLum(b);if(x==null||y==null)return null;return(Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
$('#contrastCheck')?.addEventListener('click',()=>{const fg=$('#fill')?.value||'#000000',bg='#ffffff',r=fvsContrast(fg,bg),o=$('#designCheckReadout');o.textContent=r==null?'Choose a solid HEX fill.':'Fill vs white contrast '+r.toFixed(2)+':1. '+(r>=7?'Strong text contrast.':r>=4.5?'Common normal-text threshold met.':r>=3?'Useful for large text/UI graphics, but not normal text.':'Low contrast for text.')});
$('#strokeCheck')?.addEventListener('click',()=>{const o=$('#designCheckReadout');if(!sel.length){o.textContent='Select artwork to inspect strokes.';return}const a=sel.map(e=>+(e.getAttribute('stroke-width')||0)),thin=a.filter(x=>x>0&&x<.5).length,none=a.filter(x=>!x).length;o.textContent=(thin?thin+' very thin stroke'+(thin===1?'':'s')+' (<0.5 units). ':'')+(none?none+' selected object'+(none===1?' has':'s have')+' no stroke. ':'')+(!thin&&!none?'Selected stroke widths are above the current thin-stroke warning threshold.':'')});

svg.addEventListener('pointerleave',()=>fvsClearSnap());
